// ─── CHART.JS INSTANCES MANAGEMENT ───
const donutCanvasRef = ref(null)
const lineCanvasRef = ref(null)
const barCanvasRef = ref(null)
const radarCanvasRef = ref(null)
const stackedBarCanvasRef = ref(null)

const activeChartInstances = []

function destroyCharts() {
  while (activeChartInstances.length > 0) {
    const chart = activeChartInstances.pop()
    if (chart && typeof chart.destroy === 'function') {
      chart.destroy()
    }
  }
}

onMounted(() => {
  initCharts()
})

onBeforeUnmount(() => {
  destroyCharts()
})

function initCharts() {
  destroyCharts()

  const rootStyles = getComputedStyle(document.documentElement)
  const getCssVar = (name, fallback) => rootStyles.getPropertyValue(name).trim() || fallback

  const brandGreen = getCssVar('--g-kit-lime-50', '#00ab4e')
  const brandForest = getCssVar('--g-kit-broccoli-50', '#004d43')
  const brandGold = getCssVar('--g-kit-gold-50', '#d8b56d')
  const brandOrange = getCssVar('--g-kit-orange-50', '#e07e26')
  const brandBlue = getCssVar('--g-kit-blue-50', '#1868ab')
  const textMuted = getCssVar('--g-kit-black-50', '#939597')
  const textDark = getCssVar('--g-kit-black-80', '#252528')
  const borderLine = getCssVar('--g-kit-black-20', '#eeeeef')

  // 1. Donut Chart - Komposisi TRB
  if (donutCanvasRef.value) {
    const c1 = new ChartJS(donutCanvasRef.value, {
      type: 'doughnut',
      data: {
        labels: ['Gadai Emas', 'Gadai Kendaraan', 'Gadai Properti', 'KUR Non-Gadai', 'Tabungan Emas'],
        datasets: [{
          data: [1.2, 0.85, 1.35, 1.5, 1.3],
          backgroundColor: [brandForest, brandGreen, getCssVar('--g-kit-lime-40', '#40bd63'), brandBlue, brandGold],
          borderWidth: 2,
          borderColor: getCssVar('--g-kit-white', '#ffffff'),
          hoverOffset: 6
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        cutout: '68%',
        plugins: {
          legend: {
            position: 'bottom',
            labels: { font: { family: "'Nunito Sans', sans-serif", size: 11, weight: 600 }, color: textDark, padding: 10 }
          },
          tooltip: {
            callbacks: {
              label: (ctx) => ` ${ctx.label}: Rp ${ctx.raw} Miliar`
            }
          }
        }
      }
    })
    activeChartInstances.push(c1)
  }

  // 2. Line Chart - Tren Revenue
  if (lineCanvasRef.value) {
    const c2 = new ChartJS(lineCanvasRef.value, {
      type: 'line',
      data: {
        labels: ['Jul', 'Agu', 'Sep', 'Okt', 'Nov', 'Des', 'Jan', 'Feb', 'Mar', 'Apr', 'Mei', 'Jun'],
        datasets: [{
          label: 'Revenue (Juta Rp)',
          data: [22, 24, 25, 23.5, 27, 29, 31, 28, 26, 27, 30, 26.5],
          borderColor: brandGreen,
          backgroundColor: 'rgba(0, 171, 78, 0.08)',
          borderWidth: 2.5,
          tension: 0.35,
          fill: true,
          pointBackgroundColor: brandGreen,
          pointRadius: 4,
          pointHoverRadius: 6
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { display: false },
          tooltip: {
            callbacks: {
              label: (ctx) => ` Revenue: Rp ${ctx.raw} Juta`
            }
          }
        },
        scales: {
          x: { grid: { display: false }, ticks: { font: { family: "'Nunito Sans', sans-serif", size: 10 }, color: textMuted } },
          y: { grid: { color: borderLine }, ticks: { font: { family: "'Nunito Sans', sans-serif", size: 10 }, color: textMuted, callback: (v) => `Rp ${v} Jt` } }
        }
      }
    })
    activeChartInstances.push(c2)
  }

  // 3. Bar Chart - Outstanding vs Loan
  if (barCanvasRef.value) {
    const c3 = new ChartJS(barCanvasRef.value, {
      type: 'bar',
      data: {
        labels: ['Gadai Emas', 'Gadai Kendaraan', 'Gadai Properti', 'KUR Non-Gadai'],
        datasets: [
          {
            label: 'Loan Amount (M)',
            data: [1.2, 0.85, 1.35, 1.5],
            backgroundColor: brandForest,
            borderRadius: 6
          },
          {
            label: 'Outstanding (M)',
            data: [0.78, 0.62, 0.71, 0.82],
            backgroundColor: brandOrange,
            borderRadius: 6
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            position: 'top',
            labels: { font: { family: "'Nunito Sans', sans-serif", size: 11, weight: 600 }, color: textDark }
          }
        },
        scales: {
          x: { grid: { display: false }, ticks: { font: { family: "'Nunito Sans', sans-serif", size: 10 }, color: textMuted } },
          y: { grid: { color: borderLine }, ticks: { font: { family: "'Nunito Sans', sans-serif", size: 10 }, color: textMuted, callback: (v) => `${v} M` } }
        }
      }
    })
    activeChartInstances.push(c3)
  }

  // 4. Radar Chart - Skor Dimensi
  if (radarCanvasRef.value) {
    const c4 = new ChartJS(radarCanvasRef.value, {
      type: 'radar',
      data: {
        labels: ['Loan Vol', 'Relationship', 'Revenue Value', 'Gold Balance', 'Collateral'],
        datasets: [{
          label: 'Skor Dimensi Nasabah',
          data: [92, 88, 95, 80, 90],
          backgroundColor: 'rgba(0, 171, 78, 0.2)',
          borderColor: brandGreen,
          pointBackgroundColor: brandGreen,
          borderWidth: 2
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: { legend: { display: false } },
        scales: {
          r: {
            angleLines: { color: borderLine },
            grid: { color: borderLine },
            pointLabels: { font: { family: "'Nunito Sans', sans-serif", size: 10, weight: 700 }, color: textDark },
            suggestedMin: 0,
            suggestedMax: 100,
            ticks: { display: false }
          }
        }
      }
    })
    activeChartInstances.push(c4)
  }

  // 5. Stacked Bar - Transaksi Kuartal
  if (stackedBarCanvasRef.value) {
    const c5 = new ChartJS(stackedBarCanvasRef.value, {
      type: 'bar',
      data: {
        labels: ['Q3 2025', 'Q4 2025', 'Q1 2026', 'Q2 2026'],
        datasets: [
          {
            label: 'Transaksi Gadai',
            data: [9, 8, 8, 7],
            backgroundColor: brandGreen,
            borderRadius: 4
          },
          {
            label: 'Transaksi Non-Gadai',
            data: [4, 4, 3, 4],
            backgroundColor: brandBlue,
            borderRadius: 4
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            position: 'bottom',
            labels: { font: { family: "'Nunito Sans', sans-serif", size: 11, weight: 600 }, color: textDark, padding: 12 }
          }
        },
        scales: {
          x: { stacked: true, grid: { display: false }, ticks: { font: { family: "'Nunito Sans', sans-serif", size: 10 }, color: textMuted } },
          y: { stacked: true, grid: { color: borderLine }, ticks: { font: { family: "'Nunito Sans', sans-serif", size: 10 }, color: textMuted } }
        }
      }
    })
    activeChartInstances.push(c5)
  }
}
