  }
}

.facility-card-name {
  font-size: var(--g-kit-font-size-lambda);
  line-height: var(--g-kit-line-height-lambda);
  font-weight: var(--g-kit-font-weight-bold);
  color: var(--g-kit-black-80, #252528);
}

.facility-card-sub {
  font-size: var(--g-kit-font-size-sigma);
  line-height: var(--g-kit-line-height-sigma);
  font-weight: var(--g-kit-font-weight-normal);
  color: var(--g-kit-black-50, #939597);
}

.facility-stat-strip {
  background-color: var(--g-kit-black-10, #f8f8f8);
  border: 1px solid var(--g-kit-black-20, #eeeeef);
  border-radius: 6px;
  padding: 12px 8px;
}

.facility-stat-col {
  padding: 0 4px;
}

.stat-col-border {
  border-left: 1px solid var(--g-kit-black-20, #eeeeef);
}

.stat-amt-val {
  font-size: var(--g-kit-font-size-lambda);
  line-height: var(--g-kit-line-height-lambda);
  font-weight: var(--g-kit-font-weight-bold);
  color: var(--g-kit-black-80, #252528);
}

.stat-amt-lbl {
  font-size: var(--g-kit-font-size-atom);
  line-height: var(--g-kit-line-height-atom);
  font-weight: var(--g-kit-font-weight-bold);
  letter-spacing: 0.5px;
  color: var(--g-kit-black-50, #939597);
  margin-top: 2px;
}

.progress-lbl {
  font-size: var(--g-kit-font-size-sigma);
  line-height: var(--g-kit-line-height-sigma);
  font-weight: var(--g-kit-font-weight-normal);
  color: var(--g-kit-black-50, #939597);
}

.progress-pct {
  font-size: var(--g-kit-font-size-sigma);
  line-height: var(--g-kit-line-height-sigma);
  font-weight: var(--g-kit-font-weight-bold);
}

.facility-contract-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.facility-card-kv-row {
  display: flex;
  align-items: baseline;
  gap: 4px;
  font-size: var(--g-kit-font-size-omicron);
  line-height: var(--g-kit-line-height-omicron);
}

.facility-card-kv-label {
  width: 160px;
  flex-shrink: 0;
  font-weight: var(--g-kit-font-weight-bold);
  color: var(--g-kit-black-80, #252528);
}

.facility-card-kv-colon {
  width: 4px;
  flex-shrink: 0;
  font-weight: var(--g-kit-font-weight-normal);
