/* ══════════════════════════════════════════════════════════════
   SEKSI 5: ALERTS STACKED 1 BARIS 1 ALERT (GAMBAR 3)
   ══════════════════════════════════════════════════════════════ */
:deep(.insight-alert-fullwidth) {
  width: 100%;

  .alert {
    margin-bottom: 0;
    font-size: var(--g-kit-font-size-omicron) !important;
    line-height: var(--g-kit-line-height-omicron) !important;
    font-weight: var(--g-kit-font-weight-normal) !important;
    color: var(--g-kit-black-80, #252528) !important;
    padding: 14px 18px !important;
  }
}

/* ══════════════════════════════════════════════════════════════
   TABEL DOKUMEN FIGMA RESMI (NODE 754:104815)
   ══════════════════════════════════════════════════════════════ */
.single-ui-table {
  border: 1px solid var(--g-kit-black-20, #eeeeef);
  border-radius: 6px;
  overflow: hidden;
}

.table-header-row {
  background-color: var(--g-kit-lime-50, #00ab4e);
  color: var(--g-kit-white, #ffffff);
  font-size: var(--g-kit-font-size-sigma);
  line-height: var(--g-kit-line-height-sigma);
  font-weight: var(--g-kit-font-weight-bold);
}

.table-data-row {
  border-top: 1px solid var(--g-kit-black-20, #eeeeef);
  background-color: var(--g-kit-white, #ffffff);
  font-size: var(--g-kit-font-size-sigma);
  line-height: var(--g-kit-line-height-sigma);
  font-weight: var(--g-kit-font-weight-normal);
  color: var(--g-kit-black-80, #252528);

  &.row-zebra {
    background-color: var(--g-kit-black-10, #f8f8f8);
  }
}

.table-col-main {
  flex: 1 0 0;
  min-width: 0;
}

.table-col-action {
  width: 140px;
  flex-shrink: 0;
}

/* ══════════════════════════════════════════════════════════════
   STICKY BOTTOM ACTION BAR (FIGMA FRAME 626649)
   ══════════════════════════════════════════════════════════════ */
